K","number":98,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1352,"name_he":"לואן קמפוס","name_en":"TBD","position":"FW","number":99,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ברזיל","is_club_captain":false},{"id":1353,"name_he":"מתן חוזז","name_en":"TBD","position":"MF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1354,"name_he":"מריוס נוביסי","name_en":"TBD","position":"FW","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"קמרון","is_club_captain":false}]},{"team_id":14,"name_he":"הפועל פתח תקווה","name_en":"Hapoel Petah Tikva","short":"הפ״ת","city":"פתח תקווה","stadium":null,"players":[{"id":1418,"name_he":"עומר כץ","name_en":"TBD","position":"GK","number":1,"tier":4,"price":2,"overall_rank":98,"rated":true,"nationality":"ישראל","is_club_captain":true},{"id":1419,"name_he":"אבישי כהן","name_en":"TBD","position":"DF","number":null,"tier":4,"price":2,"overall_rank":110,"rated":true,"nationality":"ישראל","is_club_captain":false},{"id":1420,"name_he":"אלכס מוקטו-מוסונדה","name_en":"TBD","position":"DF","number":5,"tier":4,"price":2,"overall_rank":122,"rated":true,"nationality":"זימבבואה","is_club_captain":false},{"id":1421,"name_he":"שביט מזל","name_en":"TBD","position":"FW","number":7,"tier":5,"price":1,"overall_rank":134,"rated":true,"nationality":"ישראל","is_club_captain":false},{"id":1422,"name_he":"תומר אלטמן","name_en":"TBD","position":"MF","number":8,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1423,"name_he":"רוי דוד","name_en":"TBD","position":"MF","number":16,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1424,"name_he":"ציפיקה סонגה","name_en":"TBD","position":"FW","number":17,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"זמביה","is_club_captain":false},{"id":1425,"name_he":"עמית משוח","name_en":"TBD","position":"GK","number":18,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1426,"name_he":"קארים קิมבדי","name_en":"TBD","position":"MF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"הרפובליקה הדמוקרטית של קונגו","is_club_captain":false},{"id":1427,"name_he":"סתיו ישראלי","name_en":"TBD","position":"DF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1428,"name_he":"רוי ששון","name_en":"TBD","position":"GK","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1429,"name_he":"יער זמברובסקי","name_en":"TBD","position":"DF","number":26,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1430,"name_he":"בוני אמיאן","name_en":"TBD","position":"MF","number":29,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"אירלנד","is_club_captain":false},{"id":1431,"name_he":"גיא בדש","name_en":"TBD","position":"MF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1432,"name_he":"יזן נסאר","name_en":"TBD","position":"DF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false},{"id":1433,"name_he":"אוקלידס אנדרדה","name_en":"TBD","position":"FW","number":77,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"כף ורדה","is_club_captain":false},{"id":1434,"name_he":"הראל שלום","name_en":"TBD","position":"DF","number":null,"tier":5,"price":1,"overall_rank":null,"rated":false,"nationality":"ישראל","is_club_captain":false}]}]}$json$;
  v_league UUID;
  v_season UUID;
  t        JSONB;
  p        JSONB;
  v_team   UUID;
  v_player UUID;
  v_pos    core.position;
BEGIN
  ----------------------------------------------------------------- ליגה
  INSERT INTO core.leagues (code, country_code, default_locale, timezone, names, squad_size)
  VALUES ('IL_PREMIER', 'IL', 'he', 'Asia/Jerusalem',
          jsonb_build_object(
            'he', jsonb_build_object('full', payload->'league'->>'name_he'),
            'en', jsonb_build_object('full', payload->'league'->>'name_en')),
          11)
  ON CONFLICT (code) DO UPDATE SET names = EXCLUDED.names
  RETURNING id INTO v_league;

  INSERT INTO core.external_refs (provider, entity_type, external_id, entity_id)
  VALUES ('manual_json', 'league', payload->'league'->>'id', v_league)
  ON CONFLICT (provider, entity_type, external_id)
  DO UPDATE SET entity_id = EXCLUDED.entity_id, synced_at = now();

  ----------------------------------------------------------------- עונה
  INSERT INTO core.seasons (league_id, label, starts_on, ends_on, is_current)
  VALUES (v_league, payload->'league'->>'season', DATE '2026-08-01', DATE '2027-05-30', TRUE)
  ON CONFLICT (league_id, label) DO UPDATE SET is_current = TRUE
  RETURNING id INTO v_season;

  ---------------------------------------------------------------- קבוצות
  FOR t IN SELECT * FROM jsonb_array_elements(payload->'teams') LOOP
    SELECT entity_id INTO v_team FROM core.external_refs
     WHERE provider = 'manual_json' AND entity_type = 'team'
       AND external_id = t->>'team_id';

    IF v_team IS NULL THEN
      INSERT INTO core.teams (country_code, names, short_code)
      VALUES ('IL',
              jsonb_build_object(
                'he', jsonb_build_object('full', t->>'name_he'),
                'en', jsonb_build_object('full', t->>'name_en')),
              left(t->>'name_en', 3))
      RETURNING id INTO v_team;

      INSERT INTO core.external_refs (provider, entity_type, external_id, entity_id, payload)
      VALUES ('manual_json', 'team', t->>'team_id', v_team, t - 'players');
    ELSE
      -- מיזוג ולא דריסה: עברית שהוזנה ידנית לא נמחקת
      UPDATE core.teams
         SET names = names || jsonb_build_object(
               'he', jsonb_build_object('full', t->>'name_he'),
               'en', jsonb_build_object('full', t->>'name_en'))
       WHERE id = v_team;
    END IF;

    INSERT INTO core.team_seasons (team_id, season_id)
    VALUES (v_team, v_season) ON CONFLICT DO NOTHING;

    INSERT INTO core.entity_aliases (entity_type, entity_id, locale, alias, source)
    VALUES ('team', v_team, 'he', t->>'name_he', 'manual_json'),
           ('team', v_team, 'en', t->>'name_en', 'manual_json')
    ON CONFLICT DO NOTHING;

    -------------------------------------------------------------- שחקנים
    FOR p IN SELECT * FROM jsonb_array_elements(t->'players') LOOP
      v_pos := CASE p->>'position'
                 WHEN 'GK' THEN 'GK'
                 WHEN 'DF' THEN 'DEF'
                 WHEN 'MF' THEN 'MID'
                 WHEN 'FW' THEN 'FWD'
                 ELSE 'MID'
               END::core.position;

      SELECT entity_id INTO v_player FROM core.external_refs
       WHERE provider = 'manual_json' AND entity_type = 'player'
         AND external_id = p->>'id';

      IF v_player IS NULL THEN
        INSERT INTO core.players (names, nationality, primary_position)
        VALUES (jsonb_build_object(
                  'he', jsonb_build_object('full', p->>'name_he'),
                  'en', jsonb_build_object('full', p->>'name_en')),
                'IL', v_pos)
        RETURNING id INTO v_player;

        INSERT INTO core.external_refs (provider, entity_type, external_id, entity_id, payload)
        VALUES ('manual_json', 'player', p->>'id', v_player, p);
      ELSE
        UPDATE core.players
           SET names = names || jsonb_build_object(
                 'he', jsonb_build_object('full', p->>'name_he'),
                 'en', jsonb_build_object('full', p->>'name_en')),
               primary_position = v_pos,
               updated_at = now()
         WHERE id = v_player;
      END IF;

      INSERT INTO core.entity_aliases (entity_type, entity_id, locale, alias, source)
      VALUES ('player', v_player, 'he', p->>'name_he', 'manual_json'),
             ('player', v_player, 'en', p->>'name_en', 'manual_json')
      ON CONFLICT DO NOTHING;

      INSERT INTO core.squads (season_id, team_id, player_id, shirt_number, position, valid_from)
      VALUES (v_season, v_team, v_player, (p->>'number')::smallint, v_pos, DATE '2026-08-01')
      ON CONFLICT (season_id, team_id, player_id, valid_from)
      DO UPDATE SET shirt_number = EXCLUDED.shirt_number,
                    position     = EXCLUDED.position,
                    status       = 'active',
                    valid_to     = NULL;
    END LOOP;
  END LOOP;

  RAISE NOTICE 'סיד הושלם: % קבוצות, % שחקנים',
    jsonb_array_length(payload->'teams'),
    (SELECT count(*) FROM core.squads WHERE season_id = v_season);
END
$seed$;

-- ---------------------------------------------------------------------
-- בדיקת שפיות: כמה קבוצות יש, וכמה צריך כדי להרכיב 11 עם שחקן אחד לקבוצה
-- ---------------------------------------------------------------------
DO $check$
DECLARE
  v_teams SMALLINT;
  v_need  SMALLINT;
BEGIN
  SELECT count(*) INTO v_teams
  FROM core.team_seasons ts
  JOIN core.seasons s ON s.id = ts.season_id AND s.is_current
  JOIN core.leagues l ON l.id = s.league_id AND l.code = 'IL_PREMIER';

  SELECT squad_size INTO v_need FROM core.leagues WHERE code = 'IL_PREMIER';

  IF v_teams < v_need THEN
    RAISE WARNING
      'יש % קבוצות בעונה הנוכחית אבל ההרכב דורש % שחקנים משוֹנות. חסרות % קבוצות.',
      v_teams, v_need, v_need - v_teams;
  END IF;
END
$check$;
